/**
 * Operações sobre intervalos fechados [start, end] de números.
 *
 * Intervalos que se sobrepõem ou que se tocam num extremo ([1, 3] e [3, 5])
 * são fundidos. As funções são puras: não modificam o array recebido nem os
 * pares [start, end] dentro dele, e os pares devolvidos são arrays novos.
 */

function validate(intervals) {
  if (!Array.isArray(intervals)) throw new TypeError('intervals must be an array');
  for (const iv of intervals) {
    if (!Array.isArray(iv) || iv.length !== 2) throw new TypeError('each interval must be [start, end]');
    const [s, e] = iv;
    if (typeof s !== 'number' || typeof e !== 'number' || Number.isNaN(s) || Number.isNaN(e)) {
      throw new TypeError('interval bounds must be numbers');
    }
    if (s > e) throw new RangeError(`invalid interval [${s}, ${e}]`);
  }
}

/**
 * Funde intervalos sobrepostos ou adjacentes. Resultado ordenado por início,
 * sem sobreposições. Os pares devolvidos são sempre cópias novas.
 */
export function mergeIntervals(intervals) {
  validate(intervals);
  const sorted = intervals.map(([s, e]) => [s, e]).sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const out = [];
  for (const iv of sorted) {
    const last = out[out.length - 1];
    if (last && iv[0] <= last[1]) {
      last[1] = Math.max(last[1], iv[1]);
    } else {
      out.push([iv[0], iv[1]]);
    }
  }
  return out;
}

/**
 * Comprimento total coberto pela união dos intervalos (soma de end - start
 * dos intervalos fundidos).
 */
export function coveredLength(intervals) {
  return mergeIntervals(intervals).reduce((acc, [s, e]) => acc + (e - s), 0);
}

/**
 * true se `x` pertence a algum dos intervalos (extremos inclusos).
 */
export function covers(intervals, x) {
  return mergeIntervals(intervals).some(([s, e]) => s <= x && x <= e);
}

